// Validate tournament creation request
const {
  name,
  description,
  tournamentType,
  arenaType,
  maxParticipants,
  registrationStart,
  registrationEnd,
  startTime,
  rules,
  prizes,
  entryFee
} = $input.first().json;

if (!name || !tournamentType || !arenaType || !maxParticipants) {
  throw new Error('Name, tournament type, arena type, and max participants are required');
}

// Validate tournament type
const validTournamentTypes = ['single_elimination', 'double_elimination', 'round_robin', 'swiss', 'league'];
if (!validTournamentTypes.includes(tournamentType)) {
  throw new Error(`Invalid tournament type: ${tournamentType}`);
}

// Validate arena type
const validArenaTypes = ['1v1_duel', 'team_competition', 'battle_royale'];
if (!validArenaTypes.includes(arenaType)) {
  throw new Error(`Invalid arena type for tournament: ${arenaType}`);
}

// Generate tournament ID
const tournamentId = `tournament_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

// Set default dates if not provided
const now = new Date();
const defaultRegistrationStart = now.toISOString();
const defaultRegistrationEnd = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000).toISOString(); // 7 days from now
const defaultStartTime = new Date(now.getTime() + 14 * 24 * 60 * 60 * 1000).toISOString(); // 14 days from now

return {
  tournamentId,
  name,
  description: description || '',
  tournamentType,
  arenaType,
  maxParticipants,
  registrationStart: registrationStart || defaultRegistrationStart,
  registrationEnd: registrationEnd || defaultRegistrationEnd,
  startTime: startTime || defaultStartTime,
  rules: rules || {},
  prizes: prizes || {},
  entryFee: entryFee || 0,
  status: 'registration',
  createdAt: now.toISOString(),
  currentParticipants: 0,
  matches: [],
  bracket: null
};

// Generate tournament bracket structure based on type
const tournament = $input.first().json;
let bracket = null;

switch (tournament.tournamentType) {
  case 'single_elimination':
    bracket = this.generateSingleEliminationBracket(tournament.maxParticipants);
    break;
  case 'double_elimination':
    bracket = this.generateDoubleEliminationBracket(tournament.maxParticipants);
    break;
  case 'round_robin':
    bracket = this.generateRoundRobinBracket(tournament.maxParticipants);
    break;
  case 'swiss':
    bracket = this.generateSwissBracket(tournament.maxParticipants, tournament.rules.swissRounds || 5);
    break;
  case 'league':
    bracket = this.generateLeagueBracket(tournament.maxParticipants);
    break;
  default:
    throw new Error(`Unsupported tournament type: ${tournament.tournamentType}`);
}

return { 
  ...tournament, 
  bracket,
  estimatedDuration: this.calculateEstimatedDuration(tournament.tournamentType, tournament.maxParticipants)
};

// Helper functions
function generateSingleEliminationBracket(maxParticipants) {
  const powerOfTwo = Math.pow(2, Math.ceil(Math.log2(maxParticipants)));
  const rounds = Math.log2(powerOfTwo);
  const bracket = {
    type: 'single_elimination',
    totalSlots: powerOfTwo,
    rounds: rounds,
    matches: [],
    byes: powerOfTwo - maxParticipants
  };

  // Generate matches for each round
  for (let round = 1; round <= rounds; round++) {
    const matchesInRound = powerOfTwo / Math.pow(2, round);
    for (let match = 1; match <= matchesInRound; match++) {
      bracket.matches.push({
        id: `R${round}M${match}`,
        round: round,
        matchNumber: match,
        participants: [],
        winner: null,
        status: 'pending',
        nextMatch: round < rounds ? `R${round + 1}M${Math.ceil(match / 2)}` : null
      });
    }
  }

  return bracket;
}

function generateDoubleEliminationBracket(maxParticipants) {
  return {
    type: 'double_elimination',
    winnersBracket: generateSingleEliminationBracket(maxParticipants),
    losersBracket: {},
    grandFinal: null
  };
}

function generateRoundRobinBracket(maxParticipants) {
  const matches = [];
  const participants = Array.from({ length: maxParticipants }, (_, i) => i + 1);

  // Generate all possible matchups
  for (let i = 0; i < participants.length; i++) {
    for (let j = i + 1; j < participants.length; j++) {
      matches.push({
        id: `RR_M${matches.length + 1}`,
        participant1: participants[i],
        participant2: participants[j],
        winner: null,
        status: 'pending'
      });
    }
  }

  return {
    type: 'round_robin',
    participants: maxParticipants,
    totalMatches: matches.length,
    matches: matches
  };
}

function generateSwissBracket(maxParticipants, rounds) {
  return {
    type: 'swiss',
    participants: maxParticipants,
    rounds: rounds,
    matches: []
  };
}

function generateLeagueBracket(maxParticipants) {
  return {
    type: 'league',
    participants: maxParticipants,
    standings: []
  };
}

function calculateEstimatedDuration(type, participants) {
  const baseMatchTime = 15; // 15 minutes per match

  switch (type) {
    case 'single_elimination':
      return Math.ceil(Math.log2(participants)) * baseMatchTime;
    case 'double_elimination':
      return Math.ceil(Math.log2(participants)) * 2 * baseMatchTime;
    case 'round_robin':
      return (participants * (participants - 1) / 2) * baseMatchTime;
    case 'swiss':
      return 5 * baseMatchTime; // 5 rounds by default
    case 'league':
      return (participants - 1) * 2 * baseMatchTime; // Home and away
    default:
      return 120; // 2 hours default
  }
}

// Create tournament registration endpoints and notifications
const tournament = $input.first().json;

// Generate registration page URL
const registrationUrl = `https://dmlogn8n.com/tournaments/${tournament.tournamentId}/register`;

// Create initial notifications
const notifications = [
  {
    type: 'tournament_created',
    title: 'New Tournament Created!',
    message: `Tournament "${tournament.name}" is now open for registration!`,
    targetAudience: 'all_players',
    data: {
      tournamentId: tournament.tournamentId,
      name: tournament.name,
      arenaType: tournament.arenaType,
      maxParticipants: tournament.maxParticipants,
      entryFee: tournament.entryFee,
      registrationEnd: tournament.registrationEnd,
      startTime: tournament.startTime,
      registrationUrl: registrationUrl
    },
    timestamp: new Date().toISOString()
  }
];

// Create social media posts
const socialPosts = [
  {
    platform: 'twitter',
    content: `🏆 New tournament alert! Join "${tournament.name}" - ${tournament.arenaType} competition with ${tournament.maxParticipants} slots. Register now: ${registrationUrl} #DnD #Gaming #Tournament`,
    imageUrl: 'https://dmlogn8n.com/images/tournament-banner.jpg'
  },
  {
    platform: 'discord',
    content: `@everyone A new tournament has been created!\n\n🎮 ${tournament.name}\n📋 Type: ${tournament.tournamentType}\n⚔️ Arena: ${tournament.arenaType}\n👥 Max Participants: ${tournament.maxParticipants}\n💰 Entry Fee: ${tournament.entryFee} gold\n📅 Registration ends: ${new Date(tournament.registrationEnd).toLocaleDateString()}\n\nRegister here: ${registrationUrl}`
  }
];

return {
  tournamentId: tournament.tournamentId,
  registrationUrl,
  notifications,
  socialPosts,
  organizerActions: [
    {
      action: 'setup_broadcast',
      description: 'Configure streaming settings for tournament matches'
    },
    {
      action: 'invite_staff',
      description: 'Add referees, commentators, and moderators'
    },
    {
      action: 'configure_prizes',
      description: 'Set up automatic prize distribution'
    }
  ]
};

// Set up tournament scheduling and reminders
const tournament = $node["Save Tournament to Database"].json;
const reminders = [];

// Registration reminder (2 days before registration ends)
const registrationReminderDate = new Date(tournament.registrationEnd);
registrationReminderDate.setDate(registrationReminderDate.getDate() - 2);
reminders.push({
  id: `reg_reminder_${tournament.tournamentId}`,
  tournamentId: tournament.tournamentId,
  type: 'registration_ending',
  scheduledFor: registrationReminderDate.toISOString(),
  message: `Registration for "${tournament.name}" ends in 2 days! Don't miss out!`,
  targetAudience: 'potential_participants'
});

// Tournament start reminder (1 day before)
const startReminderDate = new Date(tournament.startTime);
startReminderDate.setDate(startReminderDate.getDate() - 1);
reminders.push({
  id: `start_reminder_${tournament.tournamentId}`,
  tournamentId: tournament.tournamentId,
  type: 'tournament_starting',
  scheduledFor: startReminderDate.toISOString(),
  message: `"${tournament.name}" starts tomorrow! Get ready for battle!`,
  targetAudience: 'registered_participants'
});

// Tournament start notification
reminders.push({
  id: `start_notification_${tournament.tournamentId}`,
  tournamentId: tournament.tournamentId,
  type: 'tournament_started',
  scheduledFor: tournament.startTime,
  message: `"${tournament.name}" has officially begun! Good luck to all participants!`,
  targetAudience: 'registered_participants'
});

return { reminders };

